/// <summary>
/// MPJ_26597_VendorGlobalV2 clear number sequence
/// </summary>
class METChangeVendLegalEntityNumberSeqToShared
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// Clear company specific number sequance and create shred one
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        NumberSequenceReference numberSequenceReference;
        NumberSequenceDatatype  numberSequenceDatatype;

        select firstOnly forUpdate numberSequenceDatatype
            where numberSequenceDatatype.DatatypeId == extendedTypeNum(METVendLegalEntityID);

        if (!numberSequenceDatatype)
        {
            return;
        }

        try
        {
            ttsBegin;

            numberSequenceReference.skipDataMethods(true);

            delete_from numberSequenceReference
                where numberSequenceReference.NumberSequenceDatatype == numberSequenceDatatype.RecId;

            delete_from numberSequenceDatatype
                where numberSequenceDatatype.DatatypeId == extendedTypeNum(METVendLegalEntityID);

            // Recreate number sequence metadata
            NumberSeqApplicationModule::loadAll();

            ttsCommit;
        }
        catch (Exception::Error)
        {
            ttsAbort;
            throw error("Failed to recreate number sequence setup for METVendLegalEntityID.");
        }
    }
